                    const used = new Set(d.lists.filter(x => x !== l).map(x => x.color)), at = TOK_LIST_COLORS.indexOf(l.color);
                    const next = [1, 2, 3, 4, 5, 6, 7].map(n => TOK_LIST_COLORS[(at + n) % TOK_LIST_COLORS.length]);
