        const BOOKMARK = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" aria-hidden="true"><path d="M4 2.2h8v11.6l-4-2.9-4 2.9z"/></svg>';
