                $('.dti-pp-foot').innerHTML = `The petpets and their colors come from the <a href="https://neopets.fandom.com/wiki/Category:Petpets" target="_blank" rel="noopener">Neopets Wiki</a>${when ? `, as of ${noteEsc(when)}` : ''}.`;
