    function init404Page() {
        GM_addStyle(`
            html, body {
                background: var(--bg) !important; color: var(--text) !important;
                font-family: 'Poppins', system-ui, sans-serif !important;
                margin: 0 !important; padding: 0 !important;
                min-height: 100vh !important;
                display: flex !important; flex-direction: column !important;
                align-items: center !important; justify-content: center !important;
                gap: 28px !important;
            }
            body > div.dialog {
                background: var(--surface) !important;
                border: 1.5px solid var(--border) !important;
                border-radius: 18px !important; padding: 32px 40px !important;
                text-align: center !important; max-width: 440px !important;
                box-shadow: 0 8px 40px rgba(0,0,0,.35) !important;
            }
            body > div.dialog h1 {
                font-size: 20px !important; font-weight: 800 !important;
                color: var(--text) !important; margin: 0 0 10px !important;
            }
            body > div.dialog p {
                font-size: 13px !important; color: var(--text-muted) !important;
                margin: 0 0 18px !important; line-height: 1.6 !important;
            }
            body > #main-nav { position: fixed !important; top: 0 !important; left: 0 !important; right: 0 !important; z-index: 1000 !important; }
            body > img[src*="404"] {
                width: 180px !important; height: 180px !important;
                object-fit: contain !important; opacity: .9 !important;
                order: -1 !important;
            }
        `);
        // The top bar too: DTI's 404 is a static page without one (the nav shows the name seen on the last page that had it)
        if (!document.getElementById('main-nav')) {
            const navEl = document.createElement('nav');
            navEl.id = 'main-nav';
            document.body.prepend(navEl);
            rebuildNav();
            if (_nstInterval) clearInterval(_nstInterval);
            _nstInterval = injectNSTClock();
        }
        // The way home: a real link
        const dialog = document.querySelector('body > div.dialog');
        if (dialog) {
            const link = document.createElement('a');
            link.href = '/'; link.textContent = '← Go back home';
            link.style.cssText = 'display:inline-block;background:var(--accent);color:#fff;border-radius:9px;padding:8px 20px;font-size:13px;font-weight:700;text-decoration:none;';
            dialog.appendChild(link);
        }
    }

