                const rank = o => { const t = o.text.toLowerCase(); return t === qq ? 0 : t.startsWith(qq) ? 1 : t.split(/[\s:-]+/).some(w => w.startsWith(qq)) ? 2 : 3; };
                const hits = opts.filter(o => !qq || o.text.toLowerCase().includes(qq));
