            pop.style.top = Math.round(below ? Math.max(8, Math.min(r.bottom + 6, innerHeight - 8 - h)) : r.top - 6 - h) + 'px';
            pop.style.left = Math.round(Math.max(8, Math.min(r.left, innerWidth - pop.offsetWidth - 8))) + 'px';
