                    menu.innerHTML = items.map(([k, t]) => `<button type="button" role="menuitem" data-k="${k}" aria-label="${t}"${k === 'delete' ? ' class="del"' : ''}>${HDR_ICO[k]}${t}</button>`).join('');
                    document.body.appendChild(menu);
